// Generated by scripts/build-coin-availability.mjs from content-source/coins/descriptions. Do not edit by hand.
// NexuAlpha's own coin descriptions (ja).
export const COIN_DESCRIPTIONS = Object.freeze({"a7a5":"A7A5はロシア・ルーブルに連動するステーブルコインで、キルギスに登録された企業が2025年に発行し、ロシアの銀行に預けたルーブル預金で裏付けられています。EthereumとTRON上で動作し、国際決済に使われています。トークンと発行元は米国・英国・EUの制裁対象となっており、利用できる場所や方法が制限されます。","aave":"AAVEは分散型レンディングプロトコルAaveのガバナンストークンです。Aaveでは、ユーザーが暗号資産を預けて他の人に貸し出したり、自分の担保を使って借り入れたりできます。保有者はアップグレードやリスク設定に投票でき、システムの不足分を補うためにAAVEをステーキングすることもできます。プロジェクトは2017年にETHLendとして始まり、元のLENDトークンは2020年にAAVEへ交換されました。","aerodrome-finance":"AEROは、Coinbaseが立ち上げたEthereumのレイヤー2「Base」上の分散型取引所・流動性ハブであるAerodrome Financeのトークンです。2023年に稼働したAerodromeはVelodromeの設計を受け継ぎ、保有者はAEROをveAEROとしてロックすることで、新規発行トークンをどの流動性プールに配分するか投票します。投票者は支持したプールの取引手数料やインセンティブの一部を受け取ります。","agora-dollar":"AUSD は Agora が2024年に発行を始めた米ドル建てステーブルコインです。各トークンは現金、短期の米国債、翌日物レポ取引で裏付けられ、準備金は VanEck が運用し、State Street が保管しています。決済や取引、DeFi に使われ、イーサリアム、Sui、Mantle、Injective、Polygon、Monad など多くのネットワークで発行されています。","akash-network":"AKT は Akash Network のネイティブトークンです。Akash は、AI の学習や推論に使う GPU を含むクラウドの計算資源を貸し借りできる分散型マーケットです。Cosmos SDK で構築されており、AKT はチェーンを守るためのステーキング、ガバナンス、計算資源の支払いに使われます。デプロイごとに公開入札が行われ、提供者同士が価格で競います。","akedo":"Akedo（AKE）はBNB Smart Chain上のトークンで、AI分野に分類されています。プロジェクトはAIツールを軸にしており、AKEは参加やインセンティブのためのエコシステムトークンとして使われます。","algorand":"Algorand（ALGO）は、MIT教授でチューリング賞受賞者のシルビオ・ミカリ氏が創設し、2019年に稼働したAlgorandブロックチェーンのネイティブ通貨です。ピュア・プルーフ・オブ・ステークを採用し、ブロック生成者は保有者の中からランダムに選ばれます。ALGOは手数料の支払いとネットワークの保護に使われ、チェーンは資産のトークン化や決済によく利用されています。","ape-and-pepe":"Ape and Pepe（APEPE）は、サルとカエルのペペというネットで人気の 2 つのキャラクターを組み合わせたミームトークンです。送金コストが比較的安い Polygon PoS ネットワーク上で動いています。多くのミームコインと同様に独自のプロトコル機能はなく、関心は主にコミュニティと取引の動きによって支えられています。","apenft":"NFT は AINFT（旧称 APENFT）のトークンで、プロジェクトは 2021 年に TRON エコシステムで始まりました。当初は著名な美術作品を NFT としてオンチェーン化し、NFT マーケットプレイスを運営することを目指していましたが、新しい名称には AI 関連サービスを含む幅広い方向性が込められています。プラットフォーム内で使われ、TRON・Ethereum・BNB Smart Chain 上に存在します。","aptos":"APTは、2022年にメインネットが稼働したプルーフ・オブ・ステーク型レイヤー1ブロックチェーン「Aptos」のネイティブトークンです。MetaのDiemブロックチェーンに携わったエンジニアが立ち上げ、スマートコントラクトにはMove言語を採用しています。APTは取引手数料の支払い、バリデーターや委任者によるネットワーク保護のためのステーキング、ガバナンスに使われます。","apxusd":"apxUSDは、イーサリアム、Base、BNB Smart Chain、Solanaで発行されている米ドル連動のステーブルコインです。約1ドルの価値を保つよう設計され、これらのネットワーク上での送金、取引、DeFiアプリの安定した単位として使われます。","arbitrum":"ARBは、Offchain Labsがオプティミスティック・ロールアップ技術で開発したイーサリアムのレイヤー2ネットワーク群、Arbitrumのガバナンストークンです。保有者はArbitrum DAOでアップグレードやトレジャリー支出に投票しますが、Arbitrum Oneの手数料はARBではなくETHで支払います。トークンは2023年3月にエアドロップで配布されました。","arweave":"AR は、2018 年に稼働したデータの永久保存に特化したブロックチェーン Arweave のネイティブトークンです。ユーザーは AR を一度支払うだけでファイルを保存でき、その一部は長期保存を支える基金に積み立てられ、マイナーはデータを保持することで AR を受け取ります。Arweave 上では、自律プログラムや AI エージェント向けの計算レイヤー AO も動いています。","aster-2":"ASTERはAsterのトークンです。Asterは無期限先物（パーペチュアル）と現物取引を中心とする分散型取引所で、主にBNB Chain上で運営されています。トークンはガバナンス、インセンティブ、プラットフォーム上の手数料関連の特典に使われます。2025年に登場し、BNB Smart Chain上のトークンとして保有されます。","avalanche-2":"アバランチ（AVAX）は、Ava Labsが2020年に立ち上げたAvalancheのネイティブトークンです。AVAXは取引手数料（支払い分はバーン）やバリデーターのステーキングに使われます。C-Chainはイーサリアム互換で、プロジェクトは独自のチェーンも立ち上げられます。発行上限は7億2,000万枚です。","axie-infinity":"AXS は、ベトナムのスタジオ Sky Mavis が開発したブロックチェーンゲーム「Axie Infinity」のガバナンス兼ステーキング用トークンです。プレイヤーは Axie と呼ばれるキャラクターを集め、繁殖させ、対戦させます。AXS はステーキングやコミュニティ資金に関する投票、繁殖などのゲーム内操作に使われ、ゲームは主に Sky Mavis が構築したイーサリアム連携チェーン Ronin で動いています。","backpack":"BP は Backpack に関連するトークンです。Backpack は Solana エコシステムから生まれた暗号資産取引所兼セルフカストディ型ウォレットで、NFT コレクション Mad Lads のチームが運営しています。Solana 上の SPL トークンとして発行され、プラットフォームのエコシステムやコミュニティ施策とユーザーをつなぐ役割を持ち、具体的な用途は Backpack チームが定めています。","basic-attention-token":"BAT（Basic Attention Token）は、トラッカーや広告の大半を標準でブロックするブラウザ Brave と結びついた ERC-20 トークンです。Brave のプライバシーに配慮した広告を表示することを選んだユーザーは BAT を受け取り、ウェブサイトやクリエイターの支援に回せます。2017 年に登場し、その後 Solana や Polygon など他のネットワークにもブリッジされています。","beldex":"BDXは、Moneroのコードを基に2018年に始まったプライバシー重視のブロックチェーン「Beldex」のネイティブコインです。リング署名やステルスアドレスなどで取引の詳細を隠し、マスターノードのネットワークがプライベートメッセンジャー「BChat」や分散型VPN「BelNet」を支えています。BDXは手数料の支払いやマスターノード運営者のステーキングに使われ、BNB Smart Chain上にはBEP-20版もあります。","bfusd":"BFUSDは、Binanceが自社プラットフォーム内で使うために作った米ドル建て資産で、パブリックブロックチェーン上では動いていません。主に先物取引の証拠金として使われ、条件はオンチェーンのプロトコルではなくBinanceが定めます。一般的なステーブルコインとは異なり、ウォレット間で自由に送ることは想定されていません。","bianrensheng":"币安人生（BinanceLife）はBNB Smart Chain上のミームトークンで、中国語の名前は「バイナンス人生」といった意味です。2025年に中国語圏の暗号資産コミュニティで、Binanceエコシステムをもじったネタとして広まりました。プロトコル上の役割や手数料用途、裏付け資産はなく、価値はコミュニティの関心だけに左右されます。","binancecoin":"BNBはBNB Chainのネイティブコインで、Binanceのエコシステムと深く結びついています。2017年にイーサリアム上のトークンとして誕生し、その後独自ネットワークへ移行しました。ガス代の支払い、バリデーターによるステーキング、ガバナンスに使われ、定期的なバーンによって流通量が恒久的に減らされています。","bitcoin":"ビットコイン（BTC）は、2009年にサトシ・ナカモトという匿名の人物が公開した最初の暗号資産です。独自のプルーフ・オブ・ワーク型ブロックチェーンで動き、マイナーがネットワークを守り取引を承認します。送金や長期的な価値の保存に使われ、発行上限は2,100万枚、新規ブロックの報酬は約4年ごとに半減します。","bitcoin-cash":"ビットコインキャッシュ（BCH）は、2017年8月にビットコインのハードフォークによって誕生した暗号資産です。支持者は、ブロックを大きくして低い手数料でより多くの取引を処理し、日常の支払いに使いやすくすることを目指しました。独自のプルーフ・オブ・ワーク型ブロックチェーンで動き、2,100万枚の上限と半減期のルールをビットコインと共有しています。","bitcoin-cash-sv":"Bitcoin SV（BSV）は、2018年11月にビットコインキャッシュから分岐したプルーフ・オブ・ワークの暗号資産です。nChainなどの支持者は、彼らが考えるビットコイン本来の設計に沿うことを目指し、非常に大きなブロックで高いオンチェーン処理能力を実現しようとしました。SHA-256でマイニングされ、発行上限は2,100万枚で、決済やデータ量の多いアプリに使われています。","bitget-token":"Bitget Token（BGB）は、取引所Bitgetのエコシステムで使われるユーティリティトークンです。取引手数料の割引や新規トークンのローンチイベントへの参加に利用でき、イーサリアムのレイヤー2ネットワークMorphのガストークンでもあります。2024年末、BitgetはBitget Wallet Token（BWB）をBGBに統合し、供給の大部分をバーンしました。","bittensor":"TAOはBittensorのネイティブ通貨です。Bittensorは参加者が機械学習モデルや計算資源を提供し、その成果の有用性に応じて報酬を受け取る分散型ネットワークです。ネットワークは専門分野ごとのサブネットに分かれており、TAOはステーキング、サブネットへの登録、サービスの支払いに使われます。ビットコインと同様に最大供給量は2,100万枚で、新規発行量は定期的に半減します。","bittorrent":"BitTorrent（BTT）はファイル共有ソフトBitTorrentに関連するトークンで、TRON創設者ジャスティン・サン氏の会社が2018年にBitTorrent Inc.を買収した後に誕生しました。BTTは高速にファイルを配布するユーザーへの報酬、分散型ストレージBTFSの支払い、BitTorrent Chainのガス代に使われます。2021年には旧BTT 1枚を新BTT 1,000枚とするデノミが行われました。","bitway":"Bitway（BTW）は分散型金融（DeFi）プロジェクトのトークンです。BNB Smart Chainとイーサリアム上でトークンとして発行されており、どちらのネットワークの一般的なウォレットでも保管できます。","blockchain-capital":"BCAPは、ベンチャーキャピタルのBlockchain Capitalが2017年に発行したデジタル証券で、同社が運用するベンチャーファンドの経済的持分を表します。最初期のトークン化投資ファンドの一つで、Ethereum上のトークンとして発行されました。ユーティリティトークンではなく証券であるため、保有や譲渡には証券規制や投資家の適格要件が適用されます。","blockstack":"STXは、ビットコイン向けのスマートコントラクト層「Stacks」（旧称Blockstack）のネイティブトークンです。Stacksは「Proof of Transfer」というコンセンサスを採用し、マイナーはBTCを投じてブロック生成に参加し、チェーンはビットコインに決済されます。STXは取引やClarity言語のスマートコントラクトの手数料に使われ、保有者は「スタッキング」でSTXをロックしてネットワークの保護に参加できます。","bnb48-club-token":"KOGE は、BNB48 Club とも呼ばれる BNB 保有者の老舗コミュニティ 48 Club のトークンです。このグループは BNB Smart Chain 上でバリデーターや関連インフラを運営しており、KOGE はコミュニティのメンバーシップやガバナンスに使われます。BNB Smart Chain 上で発行された BEP-20 トークンです。","bonk":"Bonk（BONK）はSolana上の犬をモチーフにしたミームコインで、2022年12月に供給量の半分がSolanaのユーザー、開発者、NFTコミュニティにエアドロップされて誕生しました。ステーブルコインでもガバナンストークンでもなく、コミュニティトークンとして投げ銭やトレードボット、ゲームなどのSolanaアプリで使われています。イーサリアム、BNB Smart Chain、Arbitrumなどにもブリッジ版があります。","canton-network":"Canton Coin（CC）は、規制下の金融機関向けブロックチェーン「Canton Network」のネイティブトークンで、技術はDigital Asset社が開発しました。別々のアプリがデータの機密性を保ったまま互いに決済できるのが特徴です。CCは手数料の支払いや、バリデーターとアプリ提供者への報酬に使われます。","cardano":"カルダノ（ADA）は2017年に稼働したプルーフ・オブ・ステーク型ブロックチェーンで、イーサリアム共同創業者のCharles Hoskinson氏率いるチームが研究重視の手法で開発しました。ADAは取引手数料の支払い、Ouroborosプロトコルでネットワークを守るステークプールへの委任、ガバナンス投票に使われます。名前はエイダ・ラブレスに由来し、発行上限は450億枚です。","celestia":"Celestiaはデータ可用性に特化したモジュラー型ブロックチェーンで、取引データを保存・公開することで、ロールアップなどが独自の完全な合意レイヤーを持たずに済むようにします。TIAはデータ（Blob）の投稿手数料の支払い、プルーフ・オブ・ステークのステーキング、ガバナンスに使われます。メインネットは2023年10月に稼働し、Cosmos SDKで構築されています。","chain-2":"Onyxcoin（XCN）は Onyx プロジェクトのトークンです。このプロジェクトは2022年に XCN を発行した Chain として始まり、その後 Onyx に名称を変えました。XCN は Onyx プロトコルのガバナンスや、独自の Onyx チェーンを含むエコシステム内での手数料支払いに使われます。トークンはイーサリアム、Base、BNB Smart Chain 上にも存在します。","chainlink":"チェーンリンク（LINK）は、資産価格などブロックチェーン外のデータをスマートコントラクトに届ける分散型オラクルネットワークのトークンです。LINKはノード運営者への支払いに使われ、ステーキングしてオラクルサービスの安全性を支えることもできます。クロスチェーン通信プロトコル「CCIP」も運営し、その価格フィードは多くのDeFiやトークン化資産のプロジェクトで使われています。","collector-crypt":"CARDSはCollector Cryptのトークンです。Collector CryptはSolana上のプロジェクトで、ポケモンカードなど鑑定済みの実物トレーディングカードをトークン化し、実物は専門の保管庫で管理しています。各カードはNFTとして表され、オンチェーンで売買したり実物と引き換えたりできます。CARDSはデジタルパック開封やコミュニティ向けインセンティブなど、プラットフォームのエコシステムに結び付いています。","compound-governance-token":"COMP は、Ethereum 上で最も初期のレンディングプロトコルの一つ Compound のガバナンストークンです。Compound ではユーザーが暗号資産を共有プールに預けたり、担保を差し入れて借りたりできます。COMP 保有者は対応資産や金利モデルなどの変更を提案・投票します。供給上限は 1,000 万枚で、2020 年 6 月から利用者への配布が始まりました。","conflux-token":"Conflux（CFX）はConflux Networkのネイティブ通貨で、同チェーンのメインネットは2020年に始まりました。ブロックを並列処理するTree-Graph構造を採用し、プルーフ・オブ・ワークのマイニングとプルーフ・オブ・ステークのファイナリティ層を組み合わせています。CFXは手数料の支払い、コントラクト保存のための担保、PoSステーキングに使われ、イーサリアム互換のeSpaceも提供されています。","convex-finance":"CVX は、取引所 Curve の上に構築され2021年にイーサリアムで始まった Convex Finance のトークンです。Convex を使うと、Curve の流動性提供者や CRV 保有者は自分で CRV をロックしなくても上乗せされた報酬を受け取れます。CVX 保有者はトークンを vlCVX としてロックし、Convex が持つ大きな Curve 投票権の使い道に投票でき、プロトコル手数料の一部も受け取ります。","cosmos":"ATOMは、2019年にCosmosエコシステムで最初に立ち上がったブロックチェーン「Cosmos Hub」のネイティブトークンです。プルーフ・オブ・ステーク型ネットワークを守るためのステーキング、取引手数料の支払い、オンチェーンガバナンスでの投票に使われます。Hubは通信プロトコルIBCで多くの独立したチェーンとつながっているため、ATOMはOsmosisやKavaなどのネットワーク上にも存在します。","crvusd":"crvUSD は Curve Finance が 2023 年に公開した米ドル連動のステーブルコインです。ETH やラップドビットコインなどの暗号資産を担保として預けて発行するため、過剰担保型になっています。特徴は LLAMMA という仕組みで、価格が下がると担保を一度に清算するのではなく少しずつ変換します。Ethereum と複数のレイヤー 2 の DeFi で使われています。","crypto-com-chain":"Cronos（CRO）は旧称Crypto.com Coinで、Crypto.comのチームが立ち上げたCronosブロックチェーンのネイティブトークンです。CROはCronos EVMチェーンのガス代の支払い、ネットワークを守るためのステーキング、Crypto.comエコシステム内の特典や報酬に使われます。イーサリアム上にもERC-20トークンとして存在します。","curve-dao-token":"CRVはCurve Financeのガバナンストークンです。Curveは2020年に始まった分散型取引所で、ステーブルコインなど似た資産同士を低スリッページで交換することに特化しています。CRVを最長4年ロックするとveCRVを受け取り、投票権、取引手数料の分配、CRV報酬をどのプールに配るかへの影響力を得られます。ArbitrumやPolygonなど複数のネットワークにブリッジされています。","dai":"Dai（DAI）は1米ドル付近の価値を保つよう設計された分散型ステーブルコインです。ユーザーが発行するDAIを上回る価値の暗号資産をスマートコントラクトに担保として預けることで生成されます。仕組みは当初MakerDAOが運営し、現在はSkyに名称変更しています。DAIはDeFiでの取引、レンディング、決済に広く使われ、イーサリアム上のトークンとして動作します。","dash":"Dash（DASH）は2014年に誕生した暗号資産で、当初はXCoin、次いでDarkcoinという名前でした。速くて安い支払いを目的とし、プルーフ・オブ・ワークのマイニングとマスターノードを組み合わせて、ほぼ即時に承認されるInstantSendや、プライバシーを高めるCoinJoinベースのミキシングを実現しています。各ブロック報酬の一部はトレジャリーに入り、その使い道はマスターノード保有者の投票で決まります。","decentraland":"MANA は、イーサリアム上の NFT として土地区画を所有できる3D仮想空間 Decentraland のトークンです。2017年にトークンセールを行い、2020年に一般公開されました。MANA は LAND やアバターの衣装、名前などの購入に使われ、保有者は Decentraland DAO を通じてルールや助成に投票します。イーサリアム上の ERC-20 トークンで、Polygon にもブリッジされています。","decred":"Decred（DCR）は2016年に登場した暗号資産で、プルーフ・オブ・ワークのマイニングとプルーフ・オブ・ステークの投票を組み合わせています。保有者はDCRをチケットにロックしてブロックを承認し、ルール変更に投票します。ブロック報酬の一部はトレジャリーに入り、その支出も投票で決まります。供給上限は2100万枚で、内蔵のStakeShuffleによる任意のプライバシー機能も備えています。","derive":"Derive（DRV）は旧称Lyra Financeで、オンチェーンのオプション、無期限先物、仕組み商品を扱う分散型取引所です。OP Stackで構築され、Ethereumで決済される独自のロールアップ「Derive Chain」上で動いています。DRVはガバナンスとステーキングに使われ、ステーカーは取引所の活動に連動した特典を受けられます。","dogecoin":"ドージコイン（DOGE）は、2013年にBilly MarkusとJackson Palmerが冗談として作った暗号資産で、「doge」ミームの柴犬がシンボルです。Scryptアルゴリズムを使う独自のプルーフ・オブ・ワーク型ブロックチェーンで動き、ライトコインとのマージマイニングが一般的です。投げ銭や少額決済に使われ、発行上限は定められていません。","dogwifcoin":"WIF（dogwifhat）は、ピンクのニット帽をかぶった柴犬の画像をモチーフにした Solana 上のミームコインです。2023 年末に登場し、Solana のミームトークンの中でも広く知られる存在になりました。コミュニティによる取引や拡散以外のプロトコル機能はなく、Unichain 上にもバージョンがあります。","doublezero":"2Z は DoubleZero のトークンです。DoubleZero は、ブロックチェーンのバリデーターに一般的な公衆インターネットではなく専用の高帯域光ファイバー回線を提供するネットワークプロジェクトです。最初の対象は Solana で、2Z は SPL トークンとして発行されています。トークンはネットワーク利用料の支払いと、帯域やインフラを提供する参加者への報酬に使われます。","eigenlayer":"EIGEN は EigenCloud（旧称 EigenLayer）のトークンです。Ethereum 上のプロトコルで、ステーキング済みの ETH を再ステーキング（リステーキング）し、データ可用性レイヤーやオラクル、検証可能な AI 処理などのサービスに Ethereum の経済的セキュリティを提供します。EIGEN 自体もステーキングでき、オンチェーンで不正を証明しにくいタスクを担保します。Base 上でも利用できます。","ethena":"ENAは、合成ドル「USDe」を発行するプロトコルEthenaのガバナンストークンです。USDeは銀行預金ではなく、暗号資産と、それを相殺する先物のショートポジションを組み合わせて裏付けられ、価値を1ドル付近に保つ仕組みです。ENA保有者はリスクやプロトコルに関する事項に投票でき、トークンをステーキングすることもできます。ENAは2024年にイーサリアム上で発行されました。","ethena-usde":"Ethena USDeは、Ethenaが2024年に開始した合成ドルで、1米ドル付近の価値を保つことを目指しています。銀行預金ではなく、ETHやBTCなどの暗号資産を担保として持ち、その価格変動を先物のショートポジションで相殺する「デルタニュートラル」と呼ばれる仕組みを使います。取引やDeFiで使われ、多くのネットワークで利用できます。","ether-fi":"ETHFIは、Ethereum上のリキッドステーキング・リステーキングプロトコル「ether.fi」のガバナンストークンです。利用者がETHを預けるとeETHまたはweETHを受け取り、これらはステーキングされたETHを表し、そのETHはEigenLayerを通じてリステーキングされ他のサービスの保護にも使われます。2024年に発行されたETHFIで保有者はプロトコルの意思決定に投票でき、プロジェクトは暗号資産決済カードも提供しています。","ethereum":"イーサ（ETH）は、2015年に始動したイーサリアムのネイティブ通貨です。イーサリアムはスマートコントラクトや分散型アプリを動かすブロックチェーンで、ETHは取引手数料（ガス代）の支払いや、バリデーターのステーキングに使われます。2022年にマイニングからプルーフ・オブ・ステークへ移行し、手数料の一部はバーンされます。","ethereum-classic":"イーサリアムクラシック（ETC）は、2016年のThe DAOハッキング事件をめぐる分裂後も、元のルールのまま続いているイーサリアムの元祖チェーンです。現在もプルーフ・オブ・ワークによるマイニングを採用し、イーサリアムのツールと互換性のあるスマートコントラクトに対応しています。ETCは手数料の支払いとマイナー報酬に使われ、供給上限は約2億1,070万枚です。","ethereum-name-service":"ENS は Ethereum Name Service のガバナンストークンです。このサービスは alice.eth のような読みやすい名前をウォレットアドレスなどの情報に結びつけます。保有者は ENS DAO で提案に投票し、プロトコルとトレジャリーの運営に関わります。ERC-20 トークンとして 2021 年 11 月に .eth ドメイン保有者や貢献者へエアドロップされ、最大供給量は 1 億枚です。","euro-coin":"EURCは、USDCの発行元であるCircleが発行するユーロ建てステーブルコインで、ユーロ建ての準備金により1:1で裏付けられています。2022年に（当初はEuro Coinの名称で）登場し、EUのMiCA規則に基づく電子マネートークンとして発行されています。Ethereum、Solana、Base、Avalancheなどで、ユーロ決済や為替交換、DeFiに使われています。","falcon-finance":"Falcon USD（USDf）は、Falcon Financeプロトコルが発行する合成ドルです。ユーザーはステーブルコイン、BTC、ETHなどの担保を預けてUSDfを発行し、システムは発行済みUSDfを上回る価値の担保を保持します。USDfはDeFiでドル建て資産として使えるほか、プロトコル内でステーキングしてsUSDfを受け取ることもできます。","falcon-finance-ff":"FFはFalcon Financeのガバナンス兼ユーティリティトークンです。Falcon Financeは、暗号資産、ステーブルコイン、トークン化された実物資産を担保に合成ドル「USDf」を発行するプロトコルです。保有者はFFをステーキングしてプロトコル内の特典を受けたり、各種パラメーターに投票したりできます。トークンは2025年に登場し、EthereumとBNB Smart Chainで利用できます。","fetch-ai":"FETはArtificial Superintelligence Allianceのトークンです。このアライアンスは2024年、Fetch.aiがSingularityNETのAGIX（当初はOcean ProtocolのOCEANも）とトークンを統合して誕生しました。FETはFetch.aiの自律型AIエージェントネットワークでのサービス支払い、ネットワークを守るステーキング、ガバナンスに使われ、Ethereum、Cardano、BNB Smart Chainなどに存在します。","filecoin":"Filecoin（FIL）は、Protocol Labsが開発した分散型ストレージネットワークのネイティブトークンで、メインネットは2020年に稼働しました。利用者はFILを支払ってデータを保存・取得し、ストレージ提供者はFILを担保として預け、ファイルを保管し続けることでFILを受け取ります。複製証明や時空証明といった暗号学的証明で、データが実際に保存されているかを確認します。","first-digital-usd":"First Digital USD（FDUSD）は、香港拠点のFirst Digital Group傘下のFirst Digital Labsが2023年に発行を始めた米ドル建てステーブルコインです。各トークンは、カストディで保管される現金や短期米国債などの現金同等物によって1対1で裏付けられることを目指しています。取引ペアや決済のほか、イーサリアム、BNB Smart Chain、Solana、Sui、TONなどのチェーン間でドルを移す用途に使われます。","flare-networks":"FLRは、EVM互換のレイヤー1ブロックチェーン「Flare」のネイティブトークンで、2023年1月から配布が始まり、その一部はXRP保有者へのエアドロップでした。Flareは価格データを提供するFlare Time Series Oracle（FTSO）やFlare Data Connectorなど、データ機能をプロトコル自体に組み込んでいます。FLRは手数料、ステーキング、データ提供者への委任、ガバナンスに使われます。","floki":"FLOKI は、イーロン・マスク氏の柴犬にちなんで名付けられ、2021 年に登場したコミュニティ主導のミームトークンです。ミームとしての出自に加え、ブロックチェーンゲーム Valhalla や DeFi ツール FlokiFi などを開発しており、保有者はガバナンス投票にも参加できます。Ethereum と BNB Smart Chain の両方に存在します。","frax":"FRAX は現在 Legacy Frax Dollar と表示されている、Frax Finance の最初のステーブルコインで、2020 年 12 月に米ドル連動を目指して登場しました。当初は一部担保・一部アルゴリズムという仕組みでしたが、その後は完全担保型へ移行しました。Frax はその後 frxUSD を主力のドル建てステーブルコインとして導入したため、この初期トークンはレガシー扱いになっています。","gatechain-token":"Gate（GT）は取引所Gateのエコシステムのトークンで、2019年にGateTokenとして初めて発行されました。取引手数料の割引やプラットフォームのイベントに使われ、取引所独自のブロックチェーンのガストークンでもあります。Gateは定期的にGTを買い戻してバーンしており、総供給量は徐々に減っています。","gho":"GHOは、Aaveプロトコルが2023年に発行した分散型ステーブルコインで、米ドルへの連動を目指しています。利用者はAaveに預けた暗号資産を担保にGHOを借りる形で発行するため、各GHOはそれ以上の価値の担保に裏付けられています。借入金利などのパラメーターはAaveのガバナンスが決め、Ethereumをはじめ複数のネットワークで利用できます。","global-dollar":"Global Dollar（USDG）は、Paxosが発行し、暗号資産・フィンテック企業の連合であるGlobal Dollar Networkが支える米ドル建てステーブルコインです。各USDGは現金および現金同等物の準備資産で裏付けられ、1対1でドルに交換できるよう設計されています。シンガポールのステーブルコイン規制の枠組みのもとで発行され、イーサリアム、Solana、Arbitrumなどで利用できます。","gnosis":"GNOはGnosisのトークンです。Gnosisは2015年に設立されたイーサリアム系プロジェクトで、マルチシグウォレットのSafeやCoW Swapなどのツールを生み出しました。現在GNOは主に、旧xDaiチェーンと統合したEVM互換ネットワークGnosis Chainの安全確保に使われ、バリデーターがGNOをステーキングしてブロックを生成します。保有者はGnosisDAOでの投票にもGNOを使います。","grass":"Grassは、ユーザーがブラウザ拡張機能やアプリを通じて使っていないインターネット帯域を共有し、その帯域でAI学習用の公開ウェブデータを収集するネットワークです。GRASSはSolana上のプロジェクトトークンで、参加者への報酬、ネットワークのルーターへのステーキング、ガバナンスに使われます。2024年にコミュニティ向けエアドロップで初めて配布されました。","grx-chain":"GRX は、独自ブロックチェーンで動く GRX Chain のネイティブコインで、取引所関連トークンに分類されています。この種のネイティブコインは一般に、ネットワークの取引手数料の支払いやエコシステム内での用途に使われます。","hash-2":"HASHはProvenance Blockchainのネイティブトークンです。Cosmos SDKで構築されたプルーフ・オブ・ステーク型ネットワークで、ローンや証券、ファンド記録などの金融サービス向けに設計され、米フィンテック企業Figure Technologiesが中心となって開発しました。HASHはネットワーク手数料の支払いに使われ、バリデーターや委任者がステーキングしてガバナンス投票にも参加します。","hedera-hashgraph":"HBARはHederaのネイティブ通貨です。Hederaは従来型のブロックチェーンではなく、ハッシュグラフという合意形成方式を使う公開ネットワークです。HBARは取引、スマートコントラクト、ファイル保存の手数料支払いに使われ、ネットワークの安全性を支えるためにステーキングもできます。大企業や機関で構成される評議会が運営を監督し、米ドル建てで設定された低い手数料が特徴です。","htx-dao":"HTX DAO（HTX）は、旧Huobi（フォビ）である取引所HTXのエコシステムのトークンです。2024年に登場し、保有者が提案に投票するHTX DAOのガバナンスや、プラットフォーム上の特典に使われます。旧Huobi Token（HT）の保有者はHTXに交換でき、TRON、イーサリアム、BNB Smart Chain上で流通しています。","hyperliquid":"HYPEは、無期限先物や現物取引のためのオンチェーン板（オーダーブック）を中心に構築されたレイヤー1ブロックチェーン「Hyperliquid」のネイティブトークンです。ガス代の支払い、HyperBFTコンセンサスを担うバリデーターへのステーキング、ガバナンスに使われます。2024年末に登場し、多くが初期ユーザーへのエアドロップで配布されました。","injective-protocol":"INJは、Cosmos SDKで構築されたレイヤー1ブロックチェーン「Injective」のネイティブトークンです。オーダーブック取引、デリバティブ、現実資産のトークン化といった金融アプリ向けに設計されています。INJはプルーフ・オブ・ステーク型ネットワークを守るステーキングのほか、手数料やガバナンスに使われ、プロトコル手数料の一部は定期的なバーンオークションでINJを流通から恒久的に取り除くのに使われます。","instadapp":"FLUID は、以前 Instadapp という名前だった DeFi プロトコル Fluid のガバナンストークンで、旧 INST トークンは2024年に FLUID へ名称変更されました。Fluid は共通の流動性レイヤー上で貸付と分散型取引所を組み合わせており、同じ預け入れ資産を担保としても取引用の流動性としても使えます。保有者はプロトコルのパラメーターに投票でき、イーサリアムをはじめ複数のネットワークで動いています。","internet-computer":"ICPはインターネットコンピューター（Internet Computer）のネイティブトークンです。DFINITY財団が開発し2021年に始動したブロックチェーンで、ウェブアプリ全体とそのデータをチェーン上で直接動かせます。ICPは計算やストレージの支払いに使う「サイクル」に変換でき、「ニューロン」にロックしてネットワークのガバナンス投票に参加することもできます。イーサリアムやBase上にもブリッジ版があります。","iota":"IOTA は、2016 年に始まり、ベルリンに拠点を置く IOTA Foundation が支える IOTA ネットワークのネイティブコインです。当初は IoT やデータ用途を想定した、ブロックを使わない Tangle という構造を採用していましたが、2025 年に委任型プルーフ・オブ・ステークと Move スマートコントラクトを備えた IOTA Rebased へ移行しました。ネットワーク手数料の支払いとステーキングに使われます。","janus-henderson-anemoy-aaa-clo-fund":"JAAAは、AAA格付けのローン担保証券（CLO）、つまり企業向け融資をまとめた証券に投資するファンドの持分をトークン化したものです。運用は資産運用会社のJanus Hendersonが担い、実物資産ネットワークCentrifugeと関係の深いAnemoyがオンチェーンで発行しています。Ethereum、Base、Solanaなどに存在し、通常は適格投資家のみが利用できます。","jasmycoin":"JASMY は、ソニーの元経営陣が設立した日本企業 Jasmy のトークンです。同社は IoT 機器と個人データに注目しており、デバイスが生み出すデータを本人が管理し、共有の仕方を自分で選べる仕組みを目指しています。JASMY はこのデータプラットフォームで使われる Ethereum 上の ERC-20 トークンです。","jito-governance-token":"JTOはJitoのガバナンストークンです。JitoはSolanaのプロジェクトで、リキッドステーキングトークンのJitoSOLと、取引の順序から生じる追加価値であるMEVを扱うJitoバリデータークライアントで知られています。JTO保有者はJito DAOで手数料設定やトレジャリーの用途、プロトコル変更について投票します。トークンは2023年12月にエアドロップで配布されました。","jupiter-exchange-solana":"Jupiter（JUP）は、Solana上の分散型取引所アグリゲーターJupiterのトークンです。Jupiterはスワップを多数の流動性ソースに振り分け、効率的な取引経路を探します。JUPはJupiter DAOのガバナンスに使われ、保有者は提案や新規ローンチに投票します。2024年1月に大規模なコミュニティ向けエアドロップで配布されました。","just":"JUST（JST）は、2020年にTRON上で始まった分散型金融プラットフォームJUSTのガバナンストークンです。保有者はレンディング市場JustLendなどの製品に関する提案に投票でき、JSTは一部のプロトコル手数料の支払いにも使われます。プラットフォーム収益の一部はJSTの買い戻しとバーンに充てられています。","kaia":"Kaia（KAIA）は、Kakaoが立ち上げたKlaytnとLINEが立ち上げたFinschiaが2024年に統合して誕生したレイヤー1ブロックチェーンです。どちらもアジアの大手メッセージアプリに関係するネットワークでした。KAIAは旧トークンのKLAYとFNSAを置き換え、手数料、ステーキング、ガバナンスに使われます。EVM互換で、KakaoやLINEなどから利用できるウォレットやミニアプリを重視しています。","kamino":"KMNO は、Solana 上の DeFi プラットフォーム Kamino Finance のガバナンストークンです。Kamino は貸し借り、自動化された流動性ボールト、レバレッジポジションを一つの画面にまとめています。保有者は KMNO でプロトコルの意思決定に投票でき、Kamino 内でステーキングも可能です。トークンは2024年にエアドロップで初期ユーザーへ配布されました。","kaspa":"Kaspa（KAS）は、ブロックを1本のチェーンではなく並行して生成できるblockDAG構造を採用したプルーフ・オブ・ワーク型の暗号資産です。GHOSTDAGプロトコルに基づくこの設計により、非常に短いブロック間隔と速い承認が可能になります。KASは決済や手数料に使われ、ネットワークは2021年11月にプレマインなしのフェアローンチで始まりました。","kinesis-gold":"Kinesis Gold（KAU）は金に裏付けられたデジタル通貨で、1トークンが金庫に保管された割り当て済みの金現物1グラムを表します。Kinesisの通貨システムの一部で、取引手数料の一部が利回りとして保有者や利用者に分配されます。KAUは保有・送金・支払いに使え、裏付けの金はプラットフォームの規則に従って引き出すことができます。","kinesis-silver":"KAG は Kinesis が発行するトークンで、1 枚が金庫に割り当て保管された現物の銀 1 トロイオンスに相当します。銀をデジタルで保有・送金・利用でき、発行元の条件に従って現物と引き換えることもできます。Kinesis の仕組みの中で支払いや価値の保存に使われ、Ethereum 上にもバージョンがあります。","kite-2":"KITEはKiteのネイティブトークンです。KiteはAIエージェントの決済とIDに特化したブロックチェーンで、自律的に動くソフトウェアが検証可能なIDを持ち、自らサービス代金を支払えるようにします。Avalancheの技術で構築されたEVM互換ネットワークで、KITEはステーキング、ネットワークの安全確保、ガバナンス、エコシステムのインセンティブに使われます。イーサリアム、BNB Smart Chain、Hyperliquid上にも存在します。","kucoin-shares":"KuCoin Token（KCS）は、2017年に登場した取引所KuCoinのネイティブトークンです。取引手数料の割引などプラットフォーム上の特典に使え、KuCoin Community Chain（KCC）のガストークンでもあります。KuCoinは定期的にKCSを買い戻してバーンしており、長期的に供給を1億枚まで減らす計画です。","layerzero":"ZROは、異なるブロックチェーン間でメッセージやトークンを送れるようにする相互運用プロトコル「LayerZero」のトークンです。LayerZero自体は独立したチェーンではなく、Ethereum、Arbitrum、Base、BNB Smart Chainなど多数のネットワーク上にエンドポイントのコントラクトを置いています。ZROは2024年に発行され、プロトコルのガバナンスに使われます。","leo-token":"LEO Token（LEO）は、取引所Bitfinexを運営するiFinexが2019年に発行したユーティリティトークンです。保有者はBitfinexや関連プラットフォームで、取引手数料の割引などの特典にLEOを使えます。iFinexは継続的にLEOを買い戻してバーンすると表明しており、流通量は少しずつ減っています。トークンはEthereumなどのネットワーク上にあります。","lido-dao":"LDOはLidoのガバナンストークンです。Lidoはリキッドステーキングサービスで、ETHを預けるとステーキング報酬を受け取りながらDeFiでも使えるstETHを受け取れます。LDO保有者はLido DAOでプロトコル設定やノード運営者の選定、トレジャリーの使い道について投票します。2020年末にイーサリアム上で発行され、複数のレイヤー2にもブリッジされています。","lighter":"LITは、無期限先物取引に特化した分散型取引所「Lighter」のネイティブトークンです。LighterはEthereum上のゼロ知識ロールアップとして動作し、注文のマッチングと決済が正しく行われたことを暗号学的証明で示します。LITはEthereum上で発行され、Robinhood Chain上にも存在します。","litecoin":"ライトコイン（LTC）は、2011年にCharlie Lee氏が「軽くて速いビットコイン」として公開した、初期の暗号資産の一つです。Scryptアルゴリズムを使う独自のプルーフ・オブ・ワーク型ブロックチェーンで動き、約2.5分ごとに新しいブロックが生成されます。主に決済や送金に使われ、発行上限はビットコインの4倍にあたる8,400万枚です。","mantle":"Mantle（MNT）は、取引をまとめてイーサリアム上で決済するレイヤー2ネットワーク「Mantle Network」のネイティブトークンです。Mantle上のガス代の支払いやガバナンス投票に使われます。プロジェクトはBitDAOから発展したもので、2023年にBITトークンがMNTへ転換されました。","memecore":"MemeCore（M）はミーム文化を中心に据えたプロジェクトで、ミームコインとそのコミュニティのためのブロックチェーンを掲げています。Mトークンはミームのカテゴリーに属し、BNB Smart Chain上のトークンとして利用できます。","meteora":"MET は、Solana 上の流動性プロトコル Meteora のトークンです。Meteora のプールはトレーダーや新規トークンのローンチ、その他の DeFi アプリに使われています。流動性を価格帯ごとに配置し、相場の変動に応じて手数料を調整する DLMM などの動的プールで知られています。MET は 2025 年に登場し、プロトコルのガバナンスに使われます。","midnight-3":"NIGHTは、Cardanoの開発チームが手がけ、Cardanoのパートナーチェーンとして運用されるプライバシー重視のブロックチェーン「Midnight」のネイティブトークンです。ゼロ知識証明を使い、アプリが機密データを非公開にしたままルールを守っていることを証明できます。NIGHTを保有すると取引手数料の支払いに使うシールドされたリソース「DUST」が生成され、NIGHT自体はガバナンスやブロック生成に使われます。","monad":"Monad（MON）は、2025年11月にメインネットを開始したイーサリアム互換のレイヤー1ブロックチェーンMonadのネイティブ通貨です。取引の並列実行と独自のコンセンサスMonadBFTで高い処理能力を目指しつつ、標準的なイーサリアムのスマートコントラクトをそのまま動かせます。MONはガス代の支払いに使われ、バリデーターや委任者がステーキングしてネットワークを守ります。","monero":"モネロ（XMR）は、2014年に登場したプライバシー重視の暗号資産で、取引内容を標準で秘匿します。リング署名、ステルスアドレス、秘匿取引を組み合わせ、送信者・受信者・金額を隠します。一般的なCPU向けのRandomXというプルーフ・オブ・ワーク方式で採掘され、主要な発行が終わった後も少額のブロック報酬（テールエミッション）が続きます。","morpho":"MORPHOは、イーサリアムやBaseなどのEVMネットワーク上で動く分散型レンディングプロトコルMorphoのガバナンストークンです。Morphoでは誰でも独立した貸借市場を作ることができ、外部のキュレーターが運用するボールトが預け入れ資金を各市場に配分します。MORPHO保有者はMorpho DAOでアップグレードやトレジャリーについて投票します。","mx-token":"MX は、2018年に設立された中央集権型の暗号資産取引所 MEXC のプラットフォームトークンです。MX を保有・利用すると、取引手数料の割引、新規トークンのローンチイベントへの参加、MEXC での上場投票への参加といった特典が得られます。イーサリアム上の ERC-20 トークンとして発行され、Morph L2 にも存在します。","near":"NEAR Protocol（NEAR）は2020年に稼働したプルーフ・オブ・ステーク型レイヤー1で、「Nightshade」というシャーディング設計を採用しています。NEARは取引・ストレージ手数料やステーキングに使われます。近年はAIエージェントに注力し、共同創業者Illia Polosukhin氏は論文「Attention Is All You Need」の共著者です。","neo":"NEO は、2014年に中国で Antshares（小蟻）として創設され、2017年に改名されたスマートコントラクト・ブロックチェーン Neo のネイティブコインです。Neo は委任型ビザンチン耐障害性（dBFT）でコンセンサスを取ります。NEO はコンセンサスを担う評議会の選出などガバナンスに使われ、保有するとネットワーク手数料の支払いに使う別トークン GAS が生まれます。供給量は1億枚に固定され、分割できません。","nexo":"NEXOは、2018年に設立された暗号資産レンディング・デジタル資産プラットフォーム「Nexo」のトークンです。プラットフォーム上で保有するNEXOの量によってロイヤルティランクが決まり、ローン金利などのアカウント特典に影響します。もともとEthereum上のERC-20トークンとして発行され、Polygonなど他のネットワークでも利用できます。","non-playable-coin":"Non-Playable Coin（NPC）は、ゲームの背景キャラクターのように振る舞う人を揶揄するネットミーム「NPC」にちなんだミームトークンです。2023年にイーサリアムで誕生し、トークンと連動する NFT コレクションを相互に変換できるよう設計されています。その後、Solana、BNB Smart Chain、Base などのネットワークにもブリッジされました。","official-trump":"Official Trump（TRUMP）は、ドナルド・トランプ氏に関連するSolana上のミームトークンで、2025年1月の大統領就任直前に発行されました。手数料支払いやステーキングといったプロトコル上の用途はなく、コレクション兼コミュニティトークンとして扱われています。供給量の大部分は関連団体に割り当てられ、複数年のスケジュールで段階的にロック解除されます。","okb":"OKBはOKXエコシステムのユーティリティトークンです。取引手数料の割引やプラットフォーム上の特典に使われ、OKX独自のレイヤー2ネットワーク「X Layer」のガストークンでもあります。2025年の大規模なバーンにより総供給量は2,100万枚に固定され、新たなOKBは発行されません。","olympus":"OHMはOlympusのトークンです。Olympusは2021年にイーサリアムで始まったDeFiプロトコルで、トークンを支える資産のトレジャリーを保有しています。買い戻しやレンジ型の仕組みでOHMの供給を管理し、保有者はCooler Loans機能を使ってステーク済みOHMを担保にステーブルコインを借りられます。OHMはOlympusDAOのガバナンストークンでもあります。","ondo-finance":"ONDOはOndo Financeのガバナンストークンです。Ondo Financeは米国債ファンドなどの伝統的な金融資産をトークン化してブロックチェーン上に持ち込むプロジェクトです。ONDO保有者はOndoのエコシステムや製品に関する意思決定に参加できます。トークンはイーサリアム上で動作し、Ondoのトークン化商品は機関投資家とオンチェーンの一般ユーザーの両方を対象としています。","open-usd":"Open USD（OUSD）は、1米ドルの価値を保つよう設計されたステーブルコインです。Ethereum、Solana、Base、Tempoなど複数のネットワーク上でトークンとして発行され、支払いや送金、オンチェーンアプリでのドル建て残高として使えます。","optimism":"OPはOptimism Collectiveのガバナンストークンです。同コレクティブが運営するOP Mainnetは、オプティミスティック・ロールアップで取引をまとめてイーサリアムで決済するレイヤー2ネットワークです。保有者はToken Houseでアップグレードやインセンティブ、助成について投票しますが、OP Mainnetの手数料はOPではなくETHで支払います。2022年に登場し、同じOP StackがSuperchainと呼ばれるチェーン群を支えています。","origintrail":"TRAC は OriginTrail のトークンです。OriginTrail は検証可能なデータを公開・相互接続するための分散型ナレッジグラフ（DKG）を運営しており、サプライチェーンや AI アプリなどで活用されています。TRAC はネットワーク上にナレッジアセットを公開する際に使われ、データを保存・提供するノード運営者がステーキングします。イーサリアム上の ERC-20 トークンで、Base にもバージョンがあります。","pancakeswap-token":"CAKEは、2020年にBNB Smart Chainで始まり、その後Ethereum、Arbitrum、Base、Aptosなどへ広がった分散型取引所「PancakeSwap」のトークンです。利用者は自動化された流動性プールでトークンを交換し、CAKEは流動性インセンティブ、ステーキング、ガバナンス投票に使われます。プラットフォーム手数料の一部はCAKEの買い戻しとバーンに充てられ、供給量を減らしています。","pax-gold":"PAX Gold（PAXG）は、米国の規制下にある信託会社Paxosが2019年に発行した金裏付けトークンです。1トークンは、専門の保管庫にあるロンドン・グッド・デリバリー金地金1トロイオンスの所有権を表します。イーサリアムのERC-20トークンなので、金を小さな単位で保有・送金できます。","paypal-usd":"PayPal USD（PYUSD）は、PaxosがPayPalのために発行する米ドル建てステーブルコインで、2023年に登場しました。各トークンは米ドル預金、短期米国債、類似の現金同等物で裏付けられ、1対1で交換できるよう設計されています。PYUSDはPayPalやVenmo内で送金や支払いに使えるほか、イーサリアム、Solana、Arbitrumなどのブロックチェーン上でも流通しています。","pearl-2":"Pearl（PRL）は独自ブロックチェーンのネイティブコインで、AIカテゴリに分類されています。多くのレイヤー1コインと同様に、PRLはネットワーク手数料の支払いやチェーンの運営を支えるために使われます。","pendle":"Pendleは2021年に始まったDeFiプロトコルで、利回りを生む資産を元本トークン（PT）と利回りトークン（YT）の2つに分け、別々に取引できるようにします。これにより、利回りを固定したり、将来の利回りに対してポジションを取ったりできます。PENDLEトークンはガバナンスに使われ、ロックやステーキングによりプロトコル収益の分配を受け、インセンティブの配分先を決められます。","pepe":"Pepe（PEPE）は、ネットミーム「Pepe the Frog」にちなんで2023年4月にイーサリアム上でローンチされたミームコインです。正式なロードマップや組み込みの用途はなく、コミュニティトークンとして取引・共有されています。約420.69兆枚の固定供給はローンチ時にすべて発行され、他のチェーンにはブリッジ版もあります。","pi-network":"Pi（PI）はPi Networkのネイティブコインです。2019年に始まったこのプロジェクトでは、電力を大量に使うマイニングではなく、スマホアプリでコインを貯められる仕組みが採用されました。オープンメインネットは2025年2月に稼働し、それまで残高はアプリのエコシステム内でしか使えませんでした。コンセンサスはStellar Consensus Protocolをベースとし、メインネットへの移行には通常本人確認が必要です。","pieverse":"PIEVERSEはPieverseのトークンです。PieverseはAI分野のプロジェクトで、オンチェーン決済を含むAIエージェント向けのインフラを開発しています。トークンはBNB Smart Chainとイーサリアムで発行され、エコシステムへの参加に使われます。","plasma":"Plasmaはステーブルコイン決済、特にUSDT向けに設計されたレイヤー1ブロックチェーンで、USDTの手数料無料送金などの機能を備えています。EVM互換で、セキュリティ強化のため状態をビットコインにアンカーしており、メインネットのベータ版は2025年9月に始まりました。ネイティブトークンのXPLは、その他の操作の手数料支払いや、バリデーターによるステーキングに使われます。","polkadot":"DOTはポルカドット（Polkadot）のネイティブ通貨です。ポルカドットはイーサリアム共同創設者のGavin Woodが立ち上げたネットワークで、多数の専門的なブロックチェーンを共通のセキュリティ層につなぎます。DOTはオンチェーンガバナンス、ノミネーテッド・プルーフ・オブ・ステーク（NPoS）でのステーキング、接続チェーンのブロックスペース確保に使われます。メインネットは2020年に始動しました。","polygon-ecosystem-token":"POLはPolygonネットワークのネイティブトークンで、MATICのアップグレード版です。2024年9月から1対1での移行が始まりました。POLはPolygon PoSのガス代の支払いに使われ、ネットワークを守るバリデーターがステーキングします。PolygonのAggLayerでつながる他のチェーンにも対応するよう設計されています。","pudgy-penguins":"PENGUはPudgy Penguinsのトークンです。このペンギンのキャラクターブランドは2021年にEthereumのNFTコレクションとして始まり、その後おもちゃやメディアへと広がりました。PENGUは2024年12月にSolanaで発行され、NFT保有者や他の暗号資産コミュニティに広くエアドロップされました。主にコミュニティ・ミームトークンとして使われ、現在は複数のネットワークで利用できます。","pump-fun":"PUMPはPump.funのトークンです。Pump.funはSolana上のプラットフォームで、誰でも数ステップでミームコインを作成・発行でき、初期の取引はボンディングカーブ上で行われます。PUMPトークンは2025年に登場し、プラットフォームのエコシステムやコミュニティと結びついています。Solanaのトークンなので、Solana対応のウォレットで保管します。","pyth-network":"PYTHは、ブロックチェーンアプリに市場価格を届けるオラクル「Pyth Network」のトークンです。データは取引所やトレーディング会社などの一次提供者から直接届き、ネットワークはSolanaで始まった後、多くのチェーンへ広がりました。PYTHはガバナンスと、データ提供者に価格品質の責任を持たせるステーキングに使われます。","quant-network":"QNTはQuant社のトークンです。同社のOverledger技術は、異なるブロックチェーン同士や既存の企業システムをつなぐことを目指しています。企業や開発者はライセンス料やQuantネットワークへのアクセス料の支払いにQNTを使います。トークンはイーサリアム上で動作し、供給量は約1,460万QNTに制限されています。","railgun":"RAIL は、イーサリアムやその他の EVM ネットワーク向けプライバシープロトコル Railgun のガバナンストークンです。Railgun はゼロ知識証明を使い、アドレスの履歴を公開せずにシールドされた残高の中でトークンを保有・送金・交換できるようにします。RAIL をステーキングした保有者はプロトコル変更に投票でき、資産がプライバシー領域に出入りする際の手数料の一部を受け取ります。","rain":"Rain（RAIN）は、イーサリアムのレイヤー2「Arbitrum One」上で発行されたDeFi分野のトークンです。イーサリアム互換のウォレットやアプリで使え、ネットワーク手数料はRAINではなくETHで支払います。","raydium":"RAYは、2021年にSolana上で始まった自動マーケットメーカー（AMM）兼流動性プロバイダー「Raydium」のトークンです。利用者はトークンを交換したりプールに流動性を提供したりでき、Solanaの新しいトークンの多くが最初の取引プールをRaydiumに設けます。RAYはステーキングや流動性インセンティブに使われ、取引手数料の一部はRAYの買い戻しに充てられます。","re-protocol-reusd":"reUSDはRe Protocolが提供する米ドル建てトークンです。Re Protocolは、保険会社がリスクの一部を他社に移す再保険市場とオンチェーン資金をつなぐプロジェクトです。reUSDは安定したドル価値の維持を目指して設計され、再保険関連の資産に支えられています。イーサリアム、Solana、Arbitrum、Base、Avalancheなど複数のネットワークで利用できます。","render-token":"Render（RENDER）は、3DレンダリングやAI処理のためにGPUを必要とする人と、空きGPUを持つノード運営者をつなぐRender Networkのトークンです。依頼者はRENDERで作業代を支払い、運営者は完了した作業に対してRENDERを受け取ります。OTOY創業者のジュールズ・ウルバック氏が始めたプロジェクトで、2023年にイーサリアムからSolanaへ移行し、旧RNDRトークンを置き換えました。","ripple":"XRPは、2012年に稼働したパブリックブロックチェーン「XRP Ledger」のネイティブ資産で、Ripple社と深い関わりがあります。高速・低コストの送金や国際決済を目的としており、マイニングではなく合意形成の仕組みで数秒のうちに取引が確定します。1,000億XRPはすべて開始時に発行され、取引ごとにごく少額の手数料が消滅します。","ripple-usd":"Ripple USD（RLUSD）はRippleが2024年12月に発行を開始した米ドル建てステーブルコインです。米ドル預金、短期米国債、現金同等物で裏付けられ、1対1で交換できるよう設計されています。RLUSDはXRP Ledgerとイーサリアムの両方でネイティブに発行されており、主に決済や機関向けの用途を想定しています。","safo":"SAFO は、パリのフィンテック企業 Spiko が提供するマネーマーケット型ファンドのトークン化された持分で、裏付けとなるファンドは資産運用会社 Amundi が運用しています。ファンドはスワップ契約を通じて翌日物金利に連動し、トークンによって条件を満たす投資家がパブリックブロックチェーン上で持分を保有・移転できます。Ethereum、Arbitrum、Base、Polygon、Starknet、Stellar など複数のネットワークで発行されています。","sei-network":"Seiは高速な取引アプリ向けに設計されたレイヤー1ブロックチェーンで、1秒未満のファイナリティと取引の並列処理を特徴とします。v2アップグレード以降は並列化されたEVMを備え、Ethereum形式のスマートコントラクトを展開できます。SEIはガス代の支払い、プルーフ・オブ・ステークのステーキング、ガバナンスに使われ、メインネットは2023年8月に稼働しました。","shiba-inu":"シバイヌ（SHIB）は、Ryoshiと名乗る匿名の作成者が2020年に立ち上げたミームトークンで、ドージコインで有名になった柴犬にちなんで名付けられました。イーサリアム上のERC-20トークンとして始まり、分散型取引所ShibaSwapやレイヤー2ネットワークShibariumを含むコミュニティのエコシステムへと広がりました。供給量は数百兆枚規模で、その一部はバーン（焼却）されています。","shuffle-2":"SHFL は、暗号資産で遊べるオンラインゲームプラットフォーム Shuffle のトークンです。Ethereum 上の ERC-20 トークンで、プラットフォーム内のリワードプログラムや保有者向けの抽選などに使われます。独立したブロックチェーンやプロトコルではなく、Shuffle というサービスそのものと密接に結びついたトークンです。","sky":"Sky（SKY）は、MakerDAOが2024年に名称変更したSkyプロトコルのガバナンストークンです。保有者は、ステーブルコインUSDSと従来のDAIを発行するプロトコルのリスク設定や担保について投票します。SKYはMKRのアップグレード版で、1 MKRは24,000 SKYに交換できます。","societe-generale-forge-eurcv":"EUR CoinVertible（EURCV）は、フランスの銀行ソシエテ・ジェネラルのデジタル資産子会社 Societe Generale-FORGE が発行するユーロ建てステーブルコインです。1トークンが1ユーロの価値になるよう設計され、発行体が保有するユーロ準備金で裏付けられています。2023年にまずイーサリアムで発行され、現在は Solana、Stellar、XRP Ledger でも利用でき、決済や清算に使われています。","sofiusd":"SoFiUSDは、米国の国法銀行免許を持つ個人向け金融企業SoFiが発行する米ドル建てステーブルコインです。発行体が保有する準備金に支えられ、1対1で米ドルに償還できるよう設計されており、規制下の米国銀行が直接発行する数少ないステーブルコインの一つです。イーサリアムとSolanaで稼働し、決済や清算での利用を想定しています。","solana":"ソラナ（SOL）は、2020年に稼働を始めたSolanaブロックチェーンのネイティブコインで、高い処理能力と低い手数料を目指して設計されています。SOLは取引手数料の支払いや、プルーフ・オブ・ステークでネットワークを守るバリデーターへのステーキングに使われます。「Proof of History」という時刻記録の仕組みが取引の順序付けを助けています。","sonic-3":"S は Sonic のネイティブコインです。Sonic は旧称 Fantom で、2024 年末に新しい名称とアップグレードされたチェーンで再始動しました。FTM 保有者は 1:1 の比率で S に交換できました。S は取引手数料の支払い、ネットワークを守るステーキング、ガバナンスに使われます。Sonic は EVM 互換で、アプリが生んだ手数料の一部を開発者が受け取れる仕組みがあります。","spiko-amundi-overnight-swap-fund-eur":"EURSAFOは、パリのフィンテック企業Spikoが資産運用会社Amundiと共同で立ち上げたユーロ建てファンドのトークン化された持分です。各トークンはファンド1口を表し、その価値はユーロの翌日物金利に連動することを目指しており、記録はパブリックブロックチェーン上で直接管理されます。Ethereum、Arbitrum、Base、Polygon、Starknet、Stellarなど複数のネットワークで発行されています。","stable-2":"STABLEは、USDTを中心としたステーブルコイン決済のために作られたレイヤー1ブロックチェーン「Stable」のネイティブトークンです。Stableでは取引手数料を別のガス用コインではなくUSDTで支払うため、一般の利用者は他のトークンを持たずにドルを送れます。STABLEはそれとは別に、ネットワークのセキュリティとガバナンスを支える役割を担います。","starknet":"STRKは、StarkWareが開発したEthereumのレイヤー2ネットワーク「Starknet」のネイティブトークンです。Starknetはバリディティ・ロールアップで、多数の取引をまとめてSTARK証明によりEthereumに正しさを示し、スマートコントラクトはCairo言語で書かれます。2024年に発行されたSTRKは、取引手数料の支払い、ステーキング、ガバナンスに使われます。","stellar":"ステラ（XLM）は、Jed McCaleb氏と非営利団体Stellar Development Foundationが2014年に立ち上げたStellarネットワークのネイティブ資産です。送金やステーブルコインの発行に重点を置き、マイニングではなく独自の合意プロトコルを採用。XLMは少額の手数料に使われ、各アカウントには最低残高が必要です。","sui":"SUIはレイヤー1ブロックチェーン「Sui」のネイティブ通貨です。SuiはMetaのDiemプロジェクト出身のエンジニアが設立したMysten Labsが開発しました。SUIは取引手数料の支払い、バリデーターへのステーキングによるネットワーク保護、ガバナンスに使われます。メインネットは2023年に公開され、プログラミング言語Moveを採用し、最大供給量は100億SUIです。","sun-token":"SUNはSUN.ioのガバナンストークンです。SUN.ioはTRONブロックチェーン上のDeFiプラットフォームで、ステーブルコインのスワップ、流動性プール、分散型取引所SunSwapを提供しています。保有者はSUNをロックして提案に投票したり、流動性マイニングでの持ち分を高めたりできます。プロジェクトは2020年、TRON創設者ジャスティン・サンのエコシステム内で始まりました。","swissborg":"BORG は、2017年に設立されたスイス拠点の暗号資産投資アプリ SwissBorg のトークンです。BORG は2024年の移行で従来の CHSB トークンに置き換わり、アプリ内で上位の会員ランクやその他の特典を利用するために使われます。イーサリアムと Solana で発行されています。","syrup":"SYRUPはMaple Financeのトークンです。Mapleは機関向けに融資を行うオンチェーンのレンディングプラットフォームで、syrupUSDCなどの商品を提供しています。SYRUPは2024年にMapleの旧トークンMPLを置き換え、1 MPLは100 SYRUPに交換できました。保有者はSYRUPをステーキングし、プロトコルのガバナンスに参加できます。","terra-luna":"Terra Luna Classic（LUNC）は旧Terraブロックチェーンのネイティブ通貨です。2022年5月、アルゴリズム型ステーブルコインUSTがドルとのペッグを失ったことで崩壊しました。その後、新しいチェーンがLUNAの名称を引き継ぎ、旧チェーンとその通貨はTerra ClassicとLUNCに改名されました。Cosmos SDKベースのこのネットワークは現在コミュニティが運営し、LUNCは手数料、ステーキング、トークンバーンの投票を含むガバナンスに使われます。","tether":"テザー（USDT）は、Tether社が2014年から発行している、1米ドルの価値を保つよう設計されたステーブルコインです。同社によると、各トークンは主に短期米国債や現金同等物からなる準備金で裏付けられています。取引や決済、プラットフォーム間のドル移動に広く使われ、Ethereum、TRON、Solanaなど多くのネットワーク上に存在します。","tether-gold":"Tether Gold（XAUT）はTether社が発行するトークンで、1単位がスイスの金庫に保管された現物の金1トロイオンスの所有権を表します。ブロックチェーン上で金を保有・移転でき、1オンス未満の小さな単位でも扱えます。XAUTはイーサリアム上のトークンとして動作し、保有者は自分のアドレスに割り当てられた具体的な金地金を確認できます。","tezos":"Tezos（XTZ）は2018年にメインネットを開始したレイヤー1ブロックチェーンです。リキッド・プルーフ・オブ・ステークを採用し、保有者は自らブロックを生成（ベイキング）するか、ベイカーに委任できます。プロトコルの更新はオンチェーンで提案・投票されるため、ハードフォークなしで進化できます。XTZは取引やスマートコントラクトの手数料に使われます。","the-graph":"The Graph（GRT）は分散型インデックスプロトコルのトークンです。このプロトコルはブロックチェーンのデータをサブグラフと呼ばれるオープンなAPIに整理し、アプリは自前のサーバーを持たずにデータを照会できます。インデクサーはGRTをステークしてサービスを提供し、デリゲーターはGRTをインデクサーに委任し、キュレーターは有用なサブグラフを示します。クエリ手数料はGRTで支払われ、メインネットは2020年12月に始まりました。","the-open-network":"Gram（GRAM）は旧称Toncoinで、The Open Network（TON）のネイティブ通貨です。TONはTelegramで設計が始まり、現在は独立したコミュニティが開発するプルーフ・オブ・ステーク型ブロックチェーンです。ネットワーク手数料の支払い、バリデーターのステーキング、Telegram内での決済やミニアプリに使われます。イーサリアムやBNB Smart Chain上にはラップ版もあります。","the-sandbox":"SAND は、Animoca Brands 傘下の仮想空間兼ゲーム制作プラットフォーム The Sandbox のトークンです。プレイヤーはデジタルの土地の上で体験を作り、所有し、運営できます。SAND は LAND やゲーム内アセットの購入、プラットフォーム手数料の支払い、ステーキングやガバナンス投票に使われます。イーサリアム上の ERC-20 トークンで、Polygon と Base にもバージョンがあります。","theta-token":"THETA は Theta Network のガバナンス兼ステーキングトークンです。Theta は 2019 年に稼働したブロックチェーンで、分散型の動画配信から始まり、最近は EdgeCloud を通じて AI や GPU の計算にも広がっています。2 種類のトークンを使い分け、THETA はバリデーターやガーディアンノードがステーキングしてチェーンを守り、TFUEL が取引やサービスの支払いに使われます。THETA の供給量は 10 億枚で固定です。","thorchain":"RUNE は THORChain のネイティブ資産です。THORChain では、BTC を ETH に替えるといったブロックチェーンをまたぐネイティブコインの交換を、ラップドトークンなしで行えます。すべての流動性プールは各資産と RUNE のペアで構成され、ノード運営者はユーザー資金を保管するボールトを守るために RUNE をボンドする必要があります。Cosmos SDK で構築され、2021 年にクロスチェーン取引を開始しました。","tradable-na-rent-financing-platform-sstn":"このトークンは、北米で家賃の支払いを資金面で支える融資枠へのエクスポージャーを表す、トークン化されたプライベートクレジットで、Tradable プラットフォームを通じて発行されています。イーサリアムのレイヤー2である zkSync 上で動作し、日常的な売買よりも機関投資家や適格投資家向けの商品です。ティッカー PC0000031 は商品コードで、保有は通常、条件を満たす参加者に限られます。","tron":"トロン（TRX）は、ジャスティン・サン氏が2017年に立ち上げたTRONブロックチェーンのネイティブコインです。TRXは帯域幅やエネルギーと呼ばれるネットワーク資源の確保に使われ、ステーキングすると、委任型プルーフ・オブ・ステークでブロックを生成する27のスーパー・リプレゼンタティブへ投票できます。USDTの送金に広く使われるネットワークの一つです。","true-usd":"TrueUSD（TUSD）は2018年に登場した米ドル建てステーブルコインで、準備金として保有するドルと1:1で交換できるよう設計されています。もともとはTrustTokenのチームが開発し、現在はTechteryxが発行しており、準備金は第三者による証明レポートで公開されています。Ethereum、TRON、BNB Smart Chainなどで、決済や取引ペア、DeFiに使われています。","trust-wallet-token":"TWT は、2018 年にバイナンスが買収したセルフカストディ型ウォレットアプリ Trust Wallet のトークンです。2020 年に導入され、手数料割引などのアプリ内特典やコミュニティ機能への参加に使われます。当初は旧 BNB Beacon Chain で発行され、現在は主に BNB Smart Chain 上で流通しています。","unibase":"UBはUnibaseのトークンです。UnibaseはAI分野のプロジェクトで、AIエージェント向けの分散型メモリ層を掲げ、エージェントがアプリをまたいで長期データを保存・共有できるようにします。トークンはBNB Smart Chainとイーサリアムで発行され、アクセスやインセンティブ、エコシステムへの参加に使われます。新しいプロジェクトのため、トークン設計は今後変わる可能性があります。","uniswap":"UNIは分散型取引所Uniswapのガバナンストークンです。Uniswapでは注文板ではなく自動化された流動性プールを通じて、ウォレットから直接トークンを交換できます。UNI保有者はプロトコルの変更やコミュニティ資金の使い道に投票できます。2020年に過去の利用者へのエアドロップで配布が始まり、その後Uniswapは独自のイーサリアムのレイヤー2「Unichain」も立ち上げました。","united-stables":"United Stables（U）は、1米ドルの価値を保つよう設計されたステーブルコインです。他のドル建てステーブルコインと同様に、ウォレットやプラットフォーム間の価値移動、取引、DeFiでの安定した単位として使われます。BNB Smart Chain、イーサリアム、TRONなど複数のネットワークで発行されています。","usa":"USAT は米ドルと1対1の価値を保つよう設計された米ドル建てステーブルコインで、イーサリアムと Celo で利用できます。USAT のようなステーブルコインは、オンチェーンでのドル価値の移動、決済や清算、取引や DeFi における安定資産として使われます。準備金の裏付けや償還条件は発行体が定めているため、発行体自身の開示情報を読んでおくとよいでしょう。","usd-coin":"USDCは、Circle社が2018年に発行を始めた米ドル連動のステーブルコインです。1トークンを1ドルと交換できるよう設計され、現金と短期米国債で裏付けられており、準備金は定期的に報告されています。取引、決済、DeFiで使われ、Ethereum、Sui、Hedera、XRP Ledgerなど多くのブロックチェーン上でネイティブに発行されています。","usd1-wlfi":"USD1はWorld Liberty Financialが2025年に発行を開始した米ドル連動型ステーブルコインです。各トークンは1対1でドルに交換できるよう設計され、現金、短期米国債、現金同等物の準備資産で裏付けられており、BitGoが保管しています。イーサリアム、BNB Smart Chain、Solana、TRONなど複数のネットワークで発行されています。","usdai":"USDaiはUSD.AIプロトコルが発行する米ドル連動トークンです。このプロトコルは、GPUなどのAI計算用ハードウェアを担保とする融資にオンチェーン資金を振り向けています。USDaiは安定した価値の単位として保有できるほか、プロトコルでステーキングしてこの融資事業に連動したステーク版を受け取ることもできます。Arbitrum、イーサリアム、Base、Plasmaで流通しています。","usdd":"USDDは、2022年にTRONネットワークで始まった米ドル連動のステーブルコインです。1ドルの価値を保つことを目指し、流通量を上回る価値の暗号資産準備によって裏付けられています。主にTRONのDeFiエコシステムでの決済、取引ペア、レンディングに使われ、イーサリアムやBNB Smart Chainでも発行されています。","usdgo":"USDGOは、米ドルと1対1で連動するよう設計されたステーブルコインです。他のドル建てステーブルコインと同じく、安定した残高の保有、ウォレット間の送金、取引やDeFiでの計算単位として使われます。Solana、イーサリアム、Morph L2で発行されています。","usds":"USDSは、旧MakerDAOであるSkyが発行する米ドル連動のステーブルコインで、2024年にDAIの後継版として登場しました。DAIとUSDSは1対1で交換できます。暗号資産や現実資産（RWA）などプロトコルに預けられた担保をもとに発行され、Ethereum、Base、Arbitrum、Solanaで流通しています。","usdtb":"USDtbは、USDeを手がけるEthenaが2024年末に発行した米ドル建てステーブルコインです。USDeとは異なり、ヘッジした暗号資産ポジションではなく、主にBlackRockのトークン化米国債ファンドBUIDLの持分と現金同等の準備金で裏付けられています。安定した決済資産として、またEthenaの他の商品を支える準備金の一部として使われます。","useless-3":"Useless Coin（USELESS）は2025年に Solana で登場したミームトークンで、「役に立たない」ことを堂々と掲げています。魅力は製品やプロトコルではなく、そのジョーク自体と周囲のオンラインコミュニティにあります。BNB Smart Chain 上にもこのトークンのバージョンがあります。","usual-usd":"USD0はUsualプロトコルが発行する米ドル建てステーブルコインで、トークン化された米国短期国債などの実物資産により1:1で裏付けられる設計です。USD0をUsualのステーキング商品に預けると、プロトコルトークンのUSUALを受け取れます。DeFiのレンディングや流動性プールの基礎資産としても使われ、Ethereumや複数のEVMチェーンで動作します。","usx":"USX は Solana 上で発行されているステーブルコインで、1トークンあたり1米ドルの価値を保つことを目指しています。他のドル連動トークンと同じく、主に決済、アプリ間での資金移動、DeFi プロトコル内の安定した単位として使われます。ペッグの維持方法や裏付け資産は発行体が定めているため、利用前に発行体が公開する準備金や担保の情報を確認するとよいでしょう。","vaulta":"Vaulta（A）は、かつてEOSと呼ばれていたブロックチェーンVaultaのネイティブ通貨です。2025年にリブランドし、EOSは1対1でAに交換されました。委任型プルーフ・オブ・ステーク（DPoS）を採用し、Web3の銀行・決済サービスを目指しています。Aはネットワーク資源の支払いに使われ、ステーキングでチェーンの安全性にも貢献できます。","vechain":"VETは、2018年に稼働したパブリックブロックチェーン「VeChainThor」のネイティブトークンで、サプライチェーンの追跡や企業利用に重点を置いています。VeChainは2トークン方式を採用しており、VETを保有するとVTHOが生成され、実際の取引手数料にはVTHOが使われます。ネットワークは、身元が明らかで審査を受けたバリデーターによるプルーフ・オブ・オーソリティ型のコンセンサスで運用されてきました。","venice-token":"Venice Token（VVV）は、Erik Voorhees氏が創設したプライバシー重視のAIプラットフォームVenice.aiのトークンです。Veniceはオープンソースモデルを運用し、ユーザーの会話を保存しません。VVVをステーキングすると、リクエストごとに支払うことなくVeniceのAI APIの利用枠の一部を得られます。2025年1月にイーサリアムのレイヤー2であるBaseでローンチされました。","virtual-protocol":"Virtuals Protocolは、主にBase上でAIエージェントを作成・共同所有できるプラットフォームで、各エージェントは独自のトークンを持てます。VIRTUALはエコシステムの基軸資産で、新しいエージェントトークンは流動性プールでVIRTUALとペアになり、エージェントのサービスや立ち上げの支払いにも使われます。前身はゲームギルドのPathDAOで、2024年にVirtualsへ名称変更しました。","whitebit":"WhiteBIT Coin（WBT）は、ウクライナで創業した暗号資産取引所WhiteBITのユーティリティトークンです。保有者はWhiteBITのエコシステム内で、取引手数料の割引やプラットフォーム機能の利用などの特典にWBTを使えます。最初はEthereumとTRON上で発行され、WhiteBITチームが開発したブロックチェーン「Whitechain」でも使われています。","world-liberty-financial":"WLFIは、2024年に始まった分散型金融プロジェクトWorld Liberty Financialのガバナンストークンで、同プロジェクトはドナルド・トランプ米大統領の一族と関係があります。保有者は、ステーブルコインUSD1などプラットフォームや製品に関する提案に投票できます。当初は譲渡できませんでしたが、2025年に取引が可能になりました。","worldcoin-wld":"WLDはWorld（旧Worldcoin）のトークンです。WorldはSam Altmanらが共同創設し、Tools for Humanityが開発するプロジェクトで、プライバシーに配慮した「唯一の人間であること」のデジタル証明World IDの提供を目指しています。認証にはOrbと呼ばれる虹彩スキャン装置を使います。WLDはガバナンスやエコシステムのインセンティブに使われ、イーサリアム、Optimism、World Chain上で動作します。","wormhole":"W は、Solana やイーサリアムなど多くのブロックチェーン同士でデータやトークンをやり取りできるようにするメッセージングプロトコル Wormhole のガバナンストークンです。チェーン間メッセージは Guardian と呼ばれる19の独立した検証者が確認します。W は2024年に大規模なコミュニティ向けエアドロップとともに登場し、ラップせずにネットワーク間を移動できるネイティブなマルチチェーントークンとして設計されています。","xdce-crowd-sale":"XDCは、XinFinが立ち上げたEVM互換ブロックチェーン「XDC Network」のネイティブコインで、貿易金融や現実資産のトークン化を主な用途としています。XDPoSと呼ばれる委任型プルーフ・オブ・ステークを採用し、マスターノードが高速かつ低コストでブロックを生成します。XDCは取引手数料の支払いとマスターノード運営者のステーキングに使われ、このページのIDにあるXDCEは初期クラウドセール時のトークンを指します。","ylds":"YLDSは、FigureがProvenanceブロックチェーン上で発行する利息付きの米ドル建てトークンです。一般的なステーブルコインと異なり、米SECに証券として登録されており、保有者に利息が支払われます。準備金は短期の高品質な資産で運用されています。ドル建てのトークンを使いつつ利息も得たい決済・精算の用途を想定しています。","zama":"ZAMA は、完全準同型暗号（FHE）の研究で知られる暗号技術企業 Zama が開発した Zama Protocol のトークンです。FHE はデータを暗号化したまま計算できる技術で、Zama はこれを使って既存のブロックチェーンに秘匿残高やプライベートなスマートコントラクトを加えます。トークンはプロトコルのサービス利用料の支払いや、ネットワークを運営するオペレーターによるステーキングに使われます。","zcash":"ジーキャッシュ（ZEC）は、2016年に登場したプライバシー重視の暗号資産で、独自のプルーフ・オブ・ワーク型ブロックチェーンで動きます。ゼロ知識証明（zk-SNARKs）により、送信者・受信者・金額を隠す「シールド取引」が可能で、透明な取引はビットコインとほぼ同じように機能します。決済に使われ、発行上限は2,100万枚です。","zebec-network":"ZBCN は Zebec Network のトークンです。Solana から始まった決済プロジェクトで、給与支払いなどに使える、資金を 1 秒ごとに受取人へ流し続けるストリーミング決済で知られています。暗号資産カードなど、デジタル資産と日常の支払いをつなぐ取り組みも進めています。ZBCN はガバナンスとステーキングに使われ、旧トークン ZBC を置き換えました。"});
